  var desc = (sc.description || '').trim();
  if (desc.length > 160) desc = desc.substring(0, 157).replace(/\s+\S*$/, '') + '…';
  var tagsLine = (sc.tags || []).length ? '<br><span style="font-size:0.7rem">' + sc.tags.map(x).join(' &middot; ') + '</span>' : '';
